{SubModule=Basic Operations in Lists, Question=Find Numbers with Even Number of Digits, TestCaseName(run_code_key)=even_digits_valid, Code=def findNumbers(nums):
    count_even = 0

    for num in nums:
        # Convert number to string and check the length
        if len(str(num)) % 2 == 0:
            count_even += 1

    return count_even

# Example usage
